		slots[2] = (ulong)&result;
		int status = Bindings.table.uiSlotsDeflateRadii(slots, slots + 2);
		if (status != Bridge.OK) {
			throw Bridge.Failure(status, "UI.DeflateRadii");
		}
		return result;
	}

